13:     `/login`,
14:     { email, senha: password },
15:     {
16:       headers: {
17:         "Content-Type": "application/json",
18:       },
19:       withCredentials: true,
20:     }
21:   );
22:   saveTokenToLocalStorage(res.data.token);
23:   return res.data.usuario;
24: };
