26: const logout = async () => {
27:   const res = await api.get(`/logout`);
28:   removeTokenFromLocalStorage();
29:   return res.data;
30: };
31: 
32: const createUsuario = async ({ nome, email, senha, tipoUsuarioId }) => {
33:   const res = await api.post(
34:     `/usuarios`,
