1: import React, { useState } from "react";
2: import { useNavigate } from "react-router-dom";
3: import { useDispatch } from "react-redux";
4: import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
5: import { faPlusCircle } from "@fortawesome/free-solid-svg-icons";
6: import { Anchor, Button, LoadingIcon, Typography } from "@nabstore/styleguide";
7: import { routes } from "@nabstore/utils";
8: import CreateEnderecoModal from "../../components/CreateEnderecoModal";
9: import useGetEnderecos from "../../hooks/useGetEnderecos";
10: import EnderecoCard from "../../components/EnderecoCard";
11: 
12: const Enderecos = ({ selectEnderecoAction }) => {
13:   const dispatch = useDispatch();
14:   const navigate = useNavigate();
15:   const { data: enderecos, isLoading, error } = useGetEnderecos();
16:   const [isCreateEnderecoModalOpen, setIsCreateEnderecoModalOpen] =
17:     useState(false);
18: 
19:   const handleSelect = (endereco) => {
20:     dispatch(selectEnderecoAction(endereco));
21:     navigate(routes.CHECKOUT);
22:   };
23: 
24:   if (isLoading) {
25:     return (
26:       <div className="container pb-5">
27:         <Anchor.GoBack path={routes.CARDS} text="Voltar aos cartões" />
28: 
29:         <div className="d-flex justify-content-center mt-4">
30:           <Typography.Title>Endereços</Typography.Title>
31:         </div>
32:         <div className="d-flex flex-column align-items-center mt-5">
33:           <LoadingIcon.Oval stroke="#2f2f2f" />
34:         </div>
35:       </div>
36:     );
37:   }
38: 
39:   const EnderecosList = () => {
40:     if (isLoading || !enderecos) {
41:       return (
42:         <div className="d-flex flex-column align-items-center mt-5">
43:           <LoadingIcon.Oval stroke="#2f2f2f" />
44:         </div>
45:       );
46:     }
47: 
48:     if (error) {
49:       return (
50:         <div className="d-flex flex-column align-items-center mt-5">
51:           <Typography.Subtitle>Erro ao carregar endereços.</Typography.Subtitle>
52:         </div>
53:       );
54:     }
55: 
56:     if (enderecos.length === 0) {
57:       return (
58:         <div className="d-flex flex-column align-items-center mt-5">
59:           <Typography.Subtitle>
60:             Você ainda não possui endereços cadastrados.
61:           </Typography.Subtitle>
62:         </div>
63:       );
64:     }
65: 
66:     return (
67:       <div className="d-flex flex-column align-items-center mb-5">
68:         {enderecos.map((endereco) => (
69:           <EnderecoCard
70:             key={endereco.id}
71:             endereco={endereco}
72:             handleSelect={handleSelect}
73:           />
74:         ))}
75:       </div>
76:     );
77:   };
78: 
79:   return (
80:     <div className="container pb-5">
81:       <CreateEnderecoModal
82:         handleClose={() => setIsCreateEnderecoModalOpen(false)}
83:         showModal={isCreateEnderecoModalOpen}
84:       />
85: 
86:       <Anchor.GoBack path={routes.CARDS} text="Voltar aos cartões" />
87: 
88:       <div className="float-end">
89:         <Button.Primary onClick={() => setIsCreateEnderecoModalOpen(true)}>
90:           <FontAwesomeIcon className="me-2" icon={faPlusCircle} /> Novo Endereço
91:         </Button.Primary>
92:       </div>
93: 
94:       <div className="d-flex justify-content-center mt-4">
95:         <Typography.Title>Endereços</Typography.Title>
96:       </div>
97: 
98:       <EnderecosList />
99:     </div>
100:   );
101: };
102: 
103: export default Enderecos;

